<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap/autoload.php';require dirname(__DIR__).'/tests/database.php';
use Hostider\Commerce\State;use Hostider\Core\Id;
$db=integrationDb();
if(($argv[1]??'')==='child'){
    $input=json_decode(stream_get_contents(STDIN),true,32,JSON_THROW_ON_ERROR);if($input['baseline']??false){require dirname(__DIR__).'/storage/review-baseline-state.php';}$db->execute('SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED');$db->execute('SET SESSION innodb_lock_wait_timeout=5');echo "READY\n";fflush(STDOUT);$samples=[];$errors=[];
    for($i=0;$i<$input['iterations'];++$i){$start=hrtime(true);try{$lock=0.0;$db->transaction(function()use($db,$input,&$lock): void{$t=hrtime(true);($input['baseline']??false?new \Hostider\Commerce\BaselineState($db):new State($db))->lock($input['customer'],$input['actor'],'attempt-create');$lock=(hrtime(true)-$t)/1e6;usleep(20000);});$samples[]=['lock_ms'=>$lock,'transaction_ms'=>(hrtime(true)-$start)/1e6];}catch(Throwable $e){$errors[]=get_class($e).':'.($e instanceof PDOException?($e->errorInfo[1]??0):$e->getCode());}}
    echo json_encode(['samples'=>$samples,'errors'=>$errors],JSON_THROW_ON_ERROR);exit;
