$runs=[];foreach([1,4,8] as $concurrency){foreach(['different','same'] as $scope){$lockWaitStart=(int)$db->execute("SHOW GLOBAL STATUS LIKE 'Innodb_row_lock_time'")->fetch()['Value'];$children=[];$shared=Id::uuid();$start=hrtime(true);$db->execute('INSERT INTO finance_wallets(id,customer_id,currency) VALUES (?,?,?)',[Id::uuid(),$shared,'TRY']);for($n=0;$n<$concurrency;++$n){$customer=$scope==='same'?$shared:Id::uuid();if($scope!=='same'){$db->execute('INSERT INTO finance_wallets(id,customer_id,currency) VALUES (?,?,?)',[Id::uuid(),$customer,'TRY']);}$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,'child'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode(['customer'=>$customer,'actor'=>Id::uuid(),'iterations'=>10,'baseline'=>str_starts_with($mode,'baseline')]));fclose($pipes[0]);$children[]=[$p,$pipes];}foreach($children as [$p,$pipes]){if(trim((string)fgets($pipes[1]))!=='READY'){throw new RuntimeException('Child not ready');}}$rows=[];$errors=[];foreach($children as [$p,$pipes]){$result=json_decode(stream_get_contents($pipes[1]),true,32,JSON_THROW_ON_ERROR);$rows=array_merge($rows,$result['samples']);$errors=array_merge($errors,$result['errors']);fclose($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[2]);if(proc_close($p)!==0||$stderr!==''){throw new RuntimeException('Benchmark child failed');}}$stats=[];foreach(['lock_ms','transaction_ms'] as $key){$values=array_column($rows,$key);sort($values);$stats[$key]=['p50'=>$values[(int)floor((count($values)-1)*.5)]??null,'p95'=>$values[(int)floor((count($values)-1)*.95)]??null,'max'=>$values?max($values):null];}$runs[]=['concurrency'=>$concurrency,'scope'=>$scope,'db_row_lock_wait_ms_total'=>(int)$db->execute("SHOW GLOBAL STATUS LIKE 'Innodb_row_lock_time'")->fetch()['Value']-$lockWaitStart,'transactions'=>count($rows),'errors'=>$errors,'elapsed_ms'=>(hrtime(true)-$start)/1e6,'metrics'=>$stats];}}
$knownCustomer=$db->execute('SELECT customer_id FROM finance_wallets ORDER BY id LIMIT 1')->fetchColumn();$plans=[];foreach(['SELECT * FROM catalog_prices ORDER BY 1 FOR UPDATE','SELECT * FROM commerce_state_versions WHERE aggregate_name=\'catalog\' LOCK IN SHARE MODE','SELECT * FROM finance_allocations WHERE customer_id=? ORDER BY id FOR UPDATE','SELECT * FROM finance_wallets WHERE customer_id=? ORDER BY id FOR UPDATE','SELECT * FROM payment_attempts WHERE customer_id=? ORDER BY id FOR UPDATE'] as $sql){$params=str_contains($sql,'?')?[$knownCustomer]:[];$plans[]=['sql'=>$sql,'explain'=>$db->execute('EXPLAIN '.$sql,$params)->fetchAll(),'analyze'=>$db->transaction(fn()=>json_decode($db->execute('ANALYZE FORMAT=JSON '.$sql,$params)->fetchColumn(),true,32,JSON_THROW_ON_ERROR))];}
echo json_encode(['label'=>$mode,'database'=>$db->execute('SELECT VERSION()')->fetchColumn(),'volume'=>$volume,'synthetic_hold_ms'=>20,'runs'=>$runs,'explain'=>$plans],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n";
